  List<List<int>> graph = [
    [1, 2],
    [2, 0, 3],
    [3],
    [2],
    [0, 2],
  ];
  int n = graph.length;

  List<int> indegree = List<int>.filled(n, 0);
  for (int i = 0; i < graph.length; i++) {
    for (int j = 0; j < graph[i].length; j++) {
      indegree[graph[i][j]]++;
    }
  }

  Queue<int> queue = Queue<int>();
  for (int i = 0; i < n; i++) {
    if (indegree[i] == 0) {
      queue.add(i);
    }
  }

  List<int> topologicalSort = [];
  while (queue.isNotEmpty) {
    int u = queue.removeFirst();
    topologicalSort.add(u);
    for (int v = 0; v < n; v++) {
      if (graph[u][v] == 1) {
        indegree[v]--;
        if (indegree[v] == 0) {
          queue.add(v);
        }
      }
    }
  }

  if (topologicalSort.length != n) {
    print("Graph contains a cycle, topological sort not possible.");
  } else {
    print("Topological Sort: ${topologicalSort.join(' -> ')}");
  }
}

