void dfs(List<List<int>> graph, int u, List<int> disc, List<int> low, List<int> parent, List<bool> visited, Queue<int> queue) {
  visited[u] = true;
  disc[u] = low[u] = (queue.isEmpty ? 0 : queue.removeFirst()) + 1;
  queue.add(u);

  for (int v = 0; v < n; v++) {
    if (!visited[v] && graph[u][v] != 0) {
      parent[v] = u;
      dfs(graph, v, disc, low, parent, visited, queue);
      low[u] = low[u] < low[v] ? low[u] : low[v];

      if (parent[u] == 0 && low[u] == disc[u]) {
        queue.add(u);
      }
    }
  }
}

