  if (colonIndex == -1) {
    return result;
  }

  String checksumStr = encoded.substring(0, colonIndex);
  String digitsStr = encoded.substring(colonIndex + 1);

  int expectedChecksum = 0;
  for (int i = 0; i < checksumStr.length; i++) {
    expectedChecksum += checksumStr.codeUnitAt(i) * (i + 1);
  }

  int sum = 0;
  for (int i = 0; i < digitsStr.length; i++) {
    int d = int.tryParse(digitsStr[i]) ?? 0;
    if (d >= 0 && d <= 9) {
      sum += d * (i + 1);
    }
  }

  if (sum != expectedChecksum) {
    return result;
  }

  int count = 0;
  for (int i = 0; i < digitsStr.length; i++) {
    if (digitsStr[i] != '0') {
      count++;
    }
  }

  for (int i = 0; i < count; i++) {
    result.add(sum % multiplier);
    sum += multiplier;
  }

  return result;
}

