List<int> fn0(List<int> floors) {
  if (floors.isEmpty) return [];
  final Map<int, int> counts = <int, int>{};
  final Set<int> uniqueFloors = <int>{};

  for (final floor in floors) {
    if (floor < 1 || floor > 100) continue;
    uniqueFloors.add(floor);
    counts[floor] = (counts[floor] ?? 0) + 1;
  }

  final List<int> result = <int>[];
  for (final floor in uniqueFloors) {
    if (!counts.containsKey(floor)) continue;
    int frequency = counts[floor]!;
    result.add(frequency);
    if (frequency > 1) {
      Map<int, int> freqCounts = <int, int>{};
      for (final f in floors) {
        freqCounts[f] = (freqCounts[f] ?? 0) + 1;
      }
      int dominantFloor = -1;
      int maxCount = 0;
      for (final f in freqCounts.keys) {
        if (freqCounts[f]! > maxCount) {
          maxCount = freqCounts[f]!;
          dominantFloor = f;
        } else if (freqCounts[f]! == maxCount && f < dominantFloor) {
          dominantFloor = f;
        }
      }
      result.add(dominantFloor);
    }
  }
