  Map<String, List<List<String>>> wordBreakAll(String s, List<String> wordDict) {
    Map<String, List<List<String>>> result = {};

    void backtrack(int index, List<String> path, List<String> remaining) {
      if (index == s.length) {
        result[s] = [path.toList()];
        return;
      }

      for (int i = index; i < s.length; i++) {
        if (wordDict.contains(s.substring(index, i + 1)) && 
            !remaining.contains(s.substring(i + 1, index))) {
          path.add(s.substring(index, i + 1));
          remaining.add(s.substring(i + 1, index));
          backtrack(i + 1, path, remaining);

          path.removeLast();
          remaining.removeLast();
        }
      }
    }

