Map<String, int> fn0(List<String> events) {
  Map<String, int> tally = {'BEGIN': 0, 'ADD': 0, 'END': 0};
  List<int> stack = [0];
  for (String event in events) {
    if (event == 'BEGIN') {
      stack.add(0);
    } else if (event == 'ADD') {
      int total = stack.last + (stack.length - 1);
      stack.add(total);
      tally['ADD'] = tally['ADD']! + total;
    } else if (event == 'END') {
      if (stack.length > 1) {
        int top = stack.removeLast();
        int below = stack.removeLast();
        tally['BEGIN'] = tally['BEGIN']! + top;
        tally['ADD'] = tally['ADD']! - below;
      }
    } else if (event == 'UNDO') {
      if (stack.length > 1) {
        int removed = stack.removeLast();
        tally['ADD'] = tally['ADD']! - removed;
      }
    }
  }
  return tally;
}

