      dir = 1;
      invert = true;
    } else {
      dir = 0;
    }
    while (temp != 0) {
      if (dir == 0) {
        temp &= temp - 1;
      } else {
        temp &= temp + 1;
      }
      dir ^= 2;
    }
    if (rotCount % 2 == 1) {
      score += invert ? -0.5 : 0.5;
    } else {
      score += invert ? 0.5 : -0.5;
    }
  }
  return score;
}

