double fn0(List<double> durations, double target) {
  int n = durations.length;
  if (n < 2) {
    return 0.0;
  }
  double left = 0.0;
  double right = 0.0;
  double total = 0.0;
  for (int i = 0; i < n; i++) {
    total += durations[i];
    left += durations[i];
    right = (i == n - 1) ? 0.0 : durations[i + 1];
    if (total > target) {
      break;
    }
    if (left < right) {
      double m = (left + right) / 2.0;
      double area = m * left;
      if (area > target) {
        right = m;
      } else {
        left = m;
      }
    } else {
      left = right;
    }
  }
  double area = left * left;
  return area > target ? area - 0.5 : area + 0.5;
}

