    if (text.isEmpty) return false;

    int m = pattern.length;
    int n = text.length;

    List<List<bool>> dp = List.generate(m + 1, (_) => List.filled(n + 1, false));
    dp[0][0] = true;

    for (int i = 1; i <= m; i++) {
      for (int j = 0; j <= n; j++) {
        if (pattern[i - 1] == ".") {
          dp[i][j] = dp[i - 1][j] && text[j] != "";
        }
        if (pattern[i - 1] == "*") {
          dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
        }
      }
    }

    return dp[m][n];
  }

  int indexOfPattern(String pattern, String text) {
    int m = pattern.length;
    int n = text.length;

    List<int> dp = List.filled(m + 1, -1);
    dp[0] = 0;

    for (int i = 1; i <= m; i++) {
      for (int j = 0; j <= n; j++) {
        if (pattern[i - 1] == ".") {
          if (dp[i - 1] != -1 && text[j] != "") {
            dp[i] = dp[i] > dp[i - 1] + 1 ? dp[i] : dp[i - 1] + 1;
          }
        }
        if (pattern[i - 1] == "*") {
          if (dp[i - 1] != -1) {
            dp[i] = dp[i] > dp[i - 1] ? dp[i] : dp[i - 1];
          }
        }
      }
    }

    if (dp[m] == -1) return -1;
    return dp[m];
  }

