  if (rows == 1 && cols == 1) return true;

  List<int> colSum = List.filled(cols, 0);
  for (int c = 0; c < cols; c++) {
    for (int r = 0; r < rows; r++) {
      colSum[c] += grid[r][c];
    }
  }

  int l = 0, r = cols - 1;
  while (l < r) {
    int m = (l + r) >> 1;
    int sum = 0;
    for (int c = 0; c < cols; c++) {
      if (c <= m) sum += colSum[c];
    }
    if (sum >= k) {
      r = m;
    } else {
      l = m + 1;
    }
  }

  for (int c = 0; c < cols; c++) {
    if (colSum[c] >= k && c > l) {
      return true;
    }
  }
  return false;
}

