List<String> fn0(String rows, int minLength) {
  if (rows.isEmpty) return [];
  final tokens = <String>[];
  final valid = <String>{};
  for (var i = 0; i < rows.length; i++) {
    final ch = rows[i];
    if (ch == '#') {
      tokens.add('');
      valid.add('${ch}$i');
    } else if (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57) {
      final count = int.parse(ch);
      final span = count.abs();
      if (span <= 0 || valid.contains('${ch}$i')) continue;
      var left = i - count;
      var right = i + count;
      while (left >= 0 && rows[left] == '#') left--;
      while (right < rows.length && rows[right] == '#') right++;
      if (left < 0 || right >= rows.length) continue;
      final seg = '${ch}$left,$right';
      valid.add(seg);
      tokens.add(seg);
    }
  }
  if (tokens.isEmpty) return [];
  final windows = <String>[];
  for (final token in tokens) {
    final parts = token.split(',');
    if (parts.length != 2) continue;
    final s = parts[0];
    final e = int.parse(parts[1]);
    if (s.length < minLength || e <= 0) continue;
    if (s.isEmpty || e > windows.length) {
      windows.add(s);
      for (var j = s.length; j < e; j++) windows.add('');
    } else {
      for (var j = s.length; j < e && windows.length < s.length; j++) {
        windows.add(s);
      }
    }
  }
  final result = <String>[];
  for (var i = 0; i < windows.length; i++) {
    if (windows[i] == '') continue;
    var left = i;
    var right = i;
    while (left > 0 && windows[left - 1] == windows[left]) left--;
    while (right + 1 < windows.length && windows[right + 1] == windows[right]) right++;
    final size = right - left + 1;
    if (size >= minLength) result.add(windows[left..right]);
  }
  result.sort();
  return result;
}

