List<int> fn0(List<String> cells) {
  final List<int> result = [];
  if (cells.isEmpty) return result;

  final Set<String> visited = {};
  bool hasSolution = false;

  for (final String cell in cells) {
    if (cell.isEmpty) continue;

    final List<String> parts = cell.split('|');
    if (parts.length != 2) continue;

    final String row = parts[0];
    final String col = parts[1];

    if (row.isEmpty || col.isEmpty) continue;

    int nr = row.length - 1;
    int nc = col.length - 1;
    int nd = 0;

    for (int r = 0; r < row.length; r++) {
      final int d = row.codeUnitAt(r) - 'a'.codeUnitAt(0);
      if (d < 0 || d > 2) continue;
      nr = r;
      break;
    }
    for (int c = 0; c < col.length; c++) {
      final int d = col.codeUnitAt(c) - '1'.codeUnitAt(0);
      if (d < 0 || d > 2) continue;
      nc = c;
      break;
    }

    if (nr <= 0 || nc <= 0) continue;

    if (visited.contains(row + col)) continue;

    visited.add(row + col);

    final List<List<bool>> matrix = List.generate(
      nr,
      (_) => List.filled(nc, false),
    );

    final List<List<int>> dirs = [
      [0, 1], [0, -1], [1, 0], [-1, 0],
    ];

    List<List<int>> stack = [
      [nr, nc],
    ];

    matrix[nr][nc] = true;

    while (stack.isNotEmpty) {
      final List<int> pos = stack.removeLast();

      for (final List<int> dir in dirs) {
        final int nr = pos[0] + dir[0];
        final int nc = pos[1] + dir[1];

        if (nr >= 0 &&
            nr < row.length &&
            nc >= 0 &&
            nc < col.length &&
            !matrix[nr][nc]) {
          final String key = row + col;
          if (key.length > nd) nd = key.length;

          matrix[nr][nc] = true;
          stack.add([nr, nc]);
        }
      }
    }

    if (matrix[0][0]) {
      hasSolution = true;
      result.add(nd);
    }
  }

  if (!hasSolution) result.add(-1);
  result.sort();

  return result;
}

