bool fn0(String initialPlaylist, List<String> operations) {
  List<String> playlist = [];
  Set<String> seen = {};
  List<int> stack = [];
  bool hasShuffle = false;

  for (String op in operations) {
    if (op.isEmpty) {
      continue;
    }

    List<String> parts = op.split(' ');
    String cmd = parts[0];

    if (cmd == 'add' || cmd == 'remove') {
      if (parts.length != 2) {
        return false;
      }

      String song = parts[1];
      bool isLocal = song.contains('|');

      if (cmd == 'add' && isLocal) {
        if (seen.contains(song)) {
          return false;
        }

        seen.add(song);
        playlist.add(song);
      } else if (cmd == 'remove' && !isLocal) {
        if (!seen.contains(song)) {
          return false;
        }

        seen.remove(song);
        playlist.removeLast();
      }
    } else if (cmd == 'shuffle' || cmd == 'repeat') {
      hasShuffle = true;
    } else if (cmd == 'queue' && parts.length > 2) {
      if (stack.isNotEmpty) {
        return false;
      }

      for (int i = 1; i < parts.length; i++) {
        String song = parts[i];
        bool isLocal = song.contains('|');

        if (isLocal) {
          stack.add(int.parse(song));
        } else if (i > 1 && parts[i - 1] == song) {
          return false;
        }
      }
    } else if (cmd == 'clear' && stack.isNotEmpty) {
      stack.clear();
    } else if (cmd == 'top' && parts.length == 2) {
      int count = int.parse(parts[1]);

      if (count <= 0 || count > stack.length) {
        return false;
      }

      List<int> results = [];

      for (int i = stack.length; i >= 0; i--) {
        if (results.length >= count) {
          break;
        }

        results.add(stack.removeLast());
      }

      playlist.sort((a, b) => a.compareTo(b));
      return results == playlist;
    }

    if (stack.isNotEmpty && stack.last == 0) {
      stack.removeLast();
    }
  }

  return playlist.isEmpty && stack.isEmpty && !hasShuffle;
}

