        if (sub < dp[i][j]) {
          dp[i][j] = sub;
        }
      }
      if (dp[i][j] != 1 << 30) {
        int m = (i + j) ~/ 2;
        if (dp[i][j] == dp[i][m] + dp[m + 1][j]) {
          dp[i][j] = dp[i][m];
        }
      }
    }
  }
  int best = dp[0][n - 1];
  int count = 0;
  for (int i = 0; i < n; i++) {
    for (int j = i + 1; j < n; j++) {
      if (dp[i][j] == best) {
