  String toString() => 'Quaternion($x, $y, $z, $w)';

  @override
  bool operator ==(Object other) =>
      other is Quaternion && x == other.x && y == other.y && z == other.z && w == other.w;

  @override
  int get hashCode => x.hashCode ^ y.hashCode ^ z.hashCode ^ w.hashCode;

  Quaternion operator +(Object other) {
    if (other is Quaternion) return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
    return Quaternion(x + other, y + other, z + other, w + other);
  }

  Quaternion operator -(Object other) {
    if (other is Quaternion) return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
    return Quaternion(x - other, y - other, z - other, w - other);
  }

  Quaternion operator *(Object other) {
    if (other is Quaternion) {
      double xx = x * other.x, xy = x * other.y, xz = x * other.z, xw = x * other.w;
      double yy = y * other.y, yz = y * other.z, yw = y * other.w;
      double zz = z * other.z, zw = z * other.w;
      return Quaternion(xx - yy - zz + w, xy + yz + zw, xz + yz - xw, yw + zw);
    }
    return Quaternion(x * other, y * other, z * other, w * other);
  }

  Quaternion operator ^(int exponent) {
    if (exponent == 0) return Quaternion(1, 0, 0, 0);
    if (exponent == 1) return this;
    final half = Quaternion(x, y, z, w) * Quaternion(x, y, z, w);
    return half ^ (exponent - 1);
  }

  double norm() => sqrt(x * x + y * y + z * z + w * w);

  Quaternion conjugate() => Quaternion(x, y, z, -w);

  Quaternion inverse() => this ^ 1;

  Quaternion normalized() => this * (1 / norm());

  Quaternion operator *(double scalar) => Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  static Quaternion fromAxisAngle(List<double> axis, double angle) {
    final cos = cos(angle / 2);
    final sin = sqrt(1 - cos * cos);
    final x = axis[0] * sin;
    final y = axis[1] * sin;
    final z = axis[2] * sin;
    return Quaternion(2 * cos * cos - 1, 2 * sin * cos, 2 * sin * sin, 0);
  }

  static Quaternion fromEuler(List<double> euler) {
    double x = euler[0], y = euler[1], z = euler[2];
    return Quaternion.fromAxisAngle([x, y, z], z);
  }
}

