    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(double scalar) {
    return Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
  }

  Quaternion operator *(Quaternion other) {
    double x1 = x, y1 = y, z1 = z, w1 = w;
    double x2 = other.x, y2 = other.y, z2 = other.z, w2 = other.w;
    return Quaternion(
      x1 * w2 + x2 * y1 + z1 * z2 - y1 * y2,
      y1 * w2 + y2 * x1 + z1 * w2 - x1 * z2,
      z1 * w2 + z2 * y1 + x1 * x2 - w1 * y2,
      w1 * w2,
    );
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  Quaternion inverse() {
    double x1 = x, y1 = y, z1 = z, w1 = w;
    return Quaternion(
      x1 * x1 + y1 * y1 + z1 * z1 + w1 * w1,
      -2 * x1 * y1 + 2 * y1 * z1 - 2 * z1 * x1,
      -2 * x1 * z1 + 2 * y1 * w1 - 2 * w1 * y1,
      x1 * x1 + y1 * y1 + z1 * z1 + w1 * w1,
    );
  }

  double norm() {
    return (x * x + y * y + z * z + w * w).sqrt();
  }

  double norm2() {
    return x * x + y * y + z * z + w * w;
  }

  static Quaternion operator +(int intValue, Quaternion other) {
    return Quaternion(intValue, other.y, other.z, other.w);
  }

  static Quaternion operator -(int intValue, Quaternion other) {
    return Quaternion(intValue, -other.y, -other.z, -other.w);
  }

  static Quaternion operator *(int intValue, Quaternion other) {
    return Quaternion(intValue * other.x, other.y, other.z, other.w);
  }

  @override
  String toString() {
    return 'q1 = $x + $y * i + $z * j + $w * k';
  }

  @override
  bool operator ==(Object other) =>
      other is Quaternion && x == other.x && y == other.y && z == other.z && w == other.w;

