  Quaternion.identity() : this(0.0, 0.0, 0.0, 1.0);

  Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  Quaternion.unit() : this(0.0, 0.0, 0.0, 1.0);

  Quaternion.random() {
    final rand = Random(0);
    return Quaternion(
      rand.nextFloat() * 2 - 1,
      rand.nextFloat() * 2 - 1,
      rand.nextFloat() * 2 - 1,
      rand.nextFloat() * 2 - 1,
    );
  }

  @override
  String toString() =>
      'q1 = $x + $y * i + $z * j + $w * k, '
      'norm(q1) = ${this.norm()}';

  @override
  bool operator ==(Object other) =>
      other is Quaternion &&
      x == other.x &&
      y == other.y &&
      z == other.z &&
      w == other.w;

  @override
  int get hashCode => x.hashCode ^ y.hashCode ^ z.hashCode ^ w.hashCode;

  Quaternion operator +(Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(Quaternion other) =>
      Quaternion(
          x * other.x - y * other.y - z * other.z + w * other.w,
          x * other.y + y * other.x - z * other.w + w * other.z,
          x * other.z + y * other.w + z * other.x + w * other.y);

  Quaternion operator -(Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  double norm() => x.abs() + y.abs() + z.abs() + w.abs();

  double inverse() => x * x + y * y + z * z + w * w == 0
      ? 0.0
      : 1 / norm();

  Quaternion conjugate() =>
      Quaternion(x, y, z, -w);

  Quaternion rotate(Quaternion axis, double angle) {
    final axisX = axis.x, axisY = axis.y, axisZ = axis.z;
    final sinAngle = angle * 0.5;
    final cosAngle = (1.0 - angle * angle) * 0.5;
    return Quaternion(
      cosAngle * x + sinAngle * axisX * y + sinAngle * axisY * z + sinAngle * axisZ * w,
      cosAngle * y - sinAngle * axisX * x + sinAngle * axisY * w + sinAngle * axisZ * z,
      cosAngle * z + sinAngle * axisX * w + sinAngle * axisY * z + sinAngle * axisZ * x,
      cosAngle * w - sinAngle * axisX * z + sinAngle * axisY * x + sinAngle * axisZ * y,
    );
  }

  void normalize() {
    final norm = norm();
    if (norm == 0.0) {
      x = 0.0;
      y = 0.0;
      z = 0.0;
      w = 0.0;
    } else {
      final inv = 1 / norm;
      x *= inv;
      y *= inv;
      z *= inv;
      w *= inv;
    }
  }
}

