  const Quaternion.left() : this(0.0, 0.0, 0.0, 1.0);

  const Quaternion.right() : this(1.0, 0.0, 0.0, 0.0);

  const Quaternion.identity() : this(0.0, 0.0, 0.0, 1.0);

  const Quaternion.fromAxisAngle(double axisX, double axisY, double axisZ, double angle) {
    double cosHalf = cos(angle / 2);
    double sinHalf = sin(angle / 2);
    return Quaternion(
      axisX * axisX * cosHalf + axisY * axisY * cosHalf,
      axisX * axisY * sinHalf - axisY * axisX * sinHalf,
      axisZ * axisZ * cosHalf + axisY * axisY * cosHalf,
      axisZ * axisY * sinHalf - axisY * axisZ * sinHalf,
    );
  }

  const Quaternion.fromBasis(List<double> v) {
    if (v.length != 4) throw ArgumentError('Invalid basis vector');
    return Quaternion(v[0], v[1], v[2], v[3]);
  }

  Quaternion operator +(const Quaternion q) {
    return Quaternion(x + q.x, y + q.y, z + q.z, w + q.w);
  }

  Quaternion operator -(const Quaternion q) {
    return Quaternion(x - q.x, y - q.y, z - q.z, w - q.w);
  }

  Quaternion operator -() {
    return Quaternion(-x, -y, -z, -w);
  }

  Quaternion operator *(const Quaternion q) {
    double xx = x * x;
    double yy = y * y;
    double zz = z * z;
    double ww = w * q.w;
    double xy = x * y;
    double yz = y * z;
    double zx = z * x;
    return Quaternion(
      xx * q.w + q.x * ww,
      xy * q.w + yz * q.x + zx * q.y,
      zz * q.w + q.z * ww,
      xx * q.y + xy * q.z + zx * q.w,
