    double yz = y * z;
    double zx = z * x;
    x = xx * q.w + q.x * ww;
    y = xy * q.w + yz * q.x + zx * q.y;
    z = zz * q.w + q.z * ww;
    w = xx * q.y + xy * q.z + zx * q.w;
    return this;
  }

