  int left = 0;
  int right = seeds.length - 1;
  while (left <= right) {
    int mid = (left + right) ~/ 2;
    if (seeds[mid] == target) {
      int lo = 0;
      int hi = mid;
      while (lo < hi) {
        int mid2 = (lo + hi) ~/ 2;
