      if (stack.isNotEmpty) {
        stack.add(stack.last);
      }
    } else if (c == 'R' && stack.isNotEmpty) {
      stack.add(stack.last);
    } else if (c == 'P' && stack.isNotEmpty) {
      String top = stack.last;
      if (top == ')' || top == '<') {
        stack.removeLast();
      } else {
        stack.add(top);
      }
    } else if (c == 'B' && stack.length >= 2) {
      String b = stack.removeLast();
      String m = stack.removeLast();
      stack.add(m + b);
    } else if (c == 'D' && stack.length >= 2) {
      String d = stack.removeLast();
      String m = stack.removeLast();
      stack.add(d + m);
    } else if (c == 'C') {
      if (stack.length >= 2) {
