      stack.add(0);
      history.add([0]);
    } else if (event == 'CLOSE') {
      if (stack.isEmpty) return 'INVALID CLOSE';
      int lastNet = stack.removeLast();
      int lastDepth = history.removeLast()[0];
      if (lastNet != 0) return 'INVALID NET=$lastNet';
      if (lastDepth == 0) return 'INVALID DEPTH=$lastDepth';
      history.add([lastDepth - 1]);
    } else if (event.startsWith('D:')) {
      int depth = int.parse(event.substring(2));
      if (depth < 0 || depth > 2) return 'INVALID DEPTH=$depth';
      history.add([depth]);
      stack.add(depth);
    } else if (event.startsWith('C:')) {
      int charge = int.parse(event.substring(2));
      if (charge < 0 || charge > 100) return 'INVALID CHARGE=$charge';
      int net = charge + lastNet;
      history.add([net]);
      stack[stack.length - 1] += net;
    }
  }
  if (stack.isNotEmpty) return 'INVALID FINAL NET=${stack.removeLast()}';
  return 'FINAL:${history.length}result=${history.isEmpty ? 0 : history.last[0]}';
}

