@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<String> playlist) {
  Map<String, int> counts = {};
  for (String track in playlist) {
    counts[track] = (counts[track] ?? 0) + 1;
  }
  List<String> keys = counts.keys.toList()..sort();
  List<int> values = counts.values.toList()..sort();
  int n = keys.length;
  if (n == 0) return false;
  if (n % 2 == 1) {
    if (values[n ~/ 2 - 1] != values[n ~/ 2]) return false;
  } else {
    bool firstHalfMonotone = true;
    for (int i = 0; i < n ~/ 2; i++) {
      if (values[i] < values[i + 1]) {
        firstHalfMonotone = false;
      }
    }
    bool secondHalfMonotone = true;
    for (int i = n ~/ 2; i < n; i++) {
      if (values[i] > values[i + 1]) {
        secondHalfMonotone = false;
      }
    }
    if (firstHalfMonotone && secondHalfMonotone) {
      int mid = keys[(n ~/ 2) - 1];
      int low = 0;
      int high = n - 1;
      while (low < high) {
        int midLow = (low + high) ~/ 2;
        int midHigh = (low + high + 1) ~/ 2;
        if (counts[keys[midLow]]! <= counts[mid]) {
          low = midLow + 1;
        } else {
          high = midHigh;
        }
      }
      int targetCount = counts[mid]! ~/ 2;
      if (counts[keys[low]]! >= targetCount) {
        return true;
      }
    }
  }
  return false;
}

