List<int> fn0(List<int> manifests) {
  if (manifests.isEmpty) return List.filled(0);
  int n = manifests.length;
  List<int> dp = List.filled(n + 1, 0);
  int maxLen = 1;
  int currentLen = 1;
  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      if (manifests[j] >= manifests[i - 1] && dp[j] + 1 >= currentLen) {
        currentLen = dp[j] + 1;
        if (currentLen > maxLen) maxLen = currentLen;
      }
    }
    dp[i] = currentLen;
    currentLen = 1;
  }
  return maxLen;
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')

List<int> fn0(List<int> phaseDurations) {
  if (phaseDurations.isEmpty) return [];
  int n = phaseDurations.length;
  List<int> dp = List.filled(n, 1);
  for (int i = 1; i < n; i++) {
    if (phaseDurations[i] < phaseDurations[i - 1]) {
      dp[i] = dp[i - 1] + 1;
    }
  }
  return dp;
}

