void fn0() {

  final List<String> roles = [
    'admin',
    'editor',
    'moderator',
    'viewer',
    'user',
    'admin',
  ];

  final Map<String, Map<String, int>> rolePermissions = {
    'admin': {
      'read': 1,
      'write': 1,
      'delete': 1,
      'admin': 1,
    },
    'editor': {
      'read': 1,
      'write': 1,
      'delete': 0,
      'admin': 0,
    },
    'moderator': {
      'read': 1,
      'write': 1,
      'delete': 1,
      'admin': 0,
    },
    'viewer': {
      'read': 1,
      'write': 0,
      'delete': 0,
      'admin': 0,
    },
    'user': {
      'read': 1,
      'write': 0,
      'delete': 0,
      'admin': 0,
    },
    'admin': {
      'read': 1,
      'write': 1,
      'delete': 1,
      'admin': 1,
    },
  };

  final Map<String, Map<String, String>> userRoles = {
    'alice': {'editor': 'editor'},
    'bob':   {'moderator': 'moderator'},
    'charlie': {'viewer': 'viewer'},
    'diana': {'user': 'user'},
  };

  final Map<String, String> currentUser = {
    'alice': 'editor',
    'bob':   'moderator',
    'charlie': 'viewer',
    'diana': 'user',
  };

  final Map<String, List<String>> resourceAccessMatrix = {
    'document1': ['admin', 'editor', 'moderator'],
    'document2': ['admin', 'editor', 'moderator'],
    'sensitive_data': ['admin', 'editor', 'moderator'],
  };

  final Map<String, Map<String, String>> resourceOwner = {
    'document1': 'alice',
    'document2': 'charlie',
    'sensitive_data': 'diana',
  };

  void logAccess(String action, String resource, String user) {
    print('[$user] $action $resource');
  }

  final Map<String, Map<String, String>> accessHistory = {};

  bool accessAllowed(String role, String resource, String action) {

    if (rolePermissions[role]!.containsKey(action)) {
      return rolePermissions[role]![action]! == 1;
    }
    return false;
  }

  bool isResourceOwner(String user, String resource) {
    return resourceOwner.containsKey(resource) && resourceOwner[resource] == user;
  }

  void grantAccess(String role, String resource, String action) {
    if (!resourceAccessMatrix.containsKey(resource)) {
      print('  ✖ Resource not found');
      return;
    }

    if (!accessAllowed(role, resource, action)) {
      print('  ✖ Access denied');
      return;
    }

    resourceAccessMatrix[resource]!.add(role);
    print('  ✓ Access granted');
  }

  void denyAccess(String role, String resource, String action) {
    if (!resourceAccessMatrix.containsKey(resource)) {
      print('  ✖ Resource not found');
      return;
    }

    if (accessAllowed(role, resource, action)) {
      resourceAccessMatrix[resource]!.remove(role);
      print('  ✖ Access denied');
    }
  }

  bool checkAccess(String role, String resource, String action) {
    return accessAllowed(role, resource, action) && isResourceOwner(role, resource);
  }

  void grantAccessToAll(String resource, String action) {
    for (final role in roles) {
      grantAccess(role, resource, action);
    }
  }

  void denyAccessToAll(String resource, String action) {
    for (final role in roles) {
      denyAccess(role, resource, action);
    }
  }

  final Map<String, Map<String, String>> elevated = {};

  void elevate(String role, String newRole) {
    if (newRole == role) {
      print('  ✖ Role cannot be the same as the original');
      return;
    }
    elevated[role] = newRole;
    print('  ➜ Elevated ${role} to ${newRole}');
  }

  void revokeAccess(String role, String resource, String action) {
    if (!resourceAccessMatrix.containsKey(resource)) {
      print('  ✖ Resource not found');
      return;
    }

    if (resourceAccessMatrix[resource]!.isEmpty) {
      print('  ✖ No permissions found for ${role} on $resource');
      return;
    }

    resourceAccessMatrix[resource]!.remove(role);
    print('  ➜ ${role} no longer has access to $resource');
  }

  bool checkAccessAfterElevation(String role, String resource, String action) {
    if (elevated.containsKey(role)) {
      return accessAllowed(elevated[role]!, resource, action);
    }
    return false;
  }

  void checkAccessHistory(String user, String resource, String action) {
    print('Access history for $user:');
    for (final entry in accessHistory.entries) {
      if (entry.key == user && entry.value == action) {
