    for (final entry in accessHistory.entries) {
      if (entry.value == action) {
        print('  ${entry.key} attempts to ${entry.value}');
      }
    }
  }

  const String adminResource = 'admin_resource';
  const String sensitiveResource = 'sensitive_data';

  void testAccessControl(String role, String resource, String action) {

    String description = switch (action) {
      'read' => 'view',
      'write' => 'edit',
      'delete' => 'remove',
      _ => 'unknown action',
    };

    print('Attempting to ${action} $resource:');
    if (checkAccess(role, resource, action)) {
      print('  ✓ Access granted');
    } else {
      print('  ✗ Access denied');
    }

    print('--- Access Control Tests ---');
    print('============================');

    if (action == 'read') {
      grantAccessToAll(resource, action);
      print('  ➜ Anyone can ${description}');

      denyAccessToAll(resource, action);
      print('  ➜ Only ${role} can ${description}');

      elevate(role, 'admin');
      print('  ➜ ${role} elevated to ${elevated[role]}');
      print('  ➜ Anyone can ${description}');

      revokeAccess(elevated[role]!, resource, action);
      print('  ➜ ${elevated[role]} no longer has access');
    } else if (action == 'write') {
      grantAccess(role, resource, action);
      print('  ➜ ${role} can ${description}');

      elevate(role, 'admin');
      print('  ➜ ${role} elevated to ${elevated[role]}');
      print('  ➜ Anyone can ${description}');

      revokeAccess(elevated[role]!, resource, action);
      print('  ➜ ${elevated[role]} no longer has access');
    } else if (action == 'delete') {
      grantAccess(role, resource, action);
      print('  ➜ ${role} can ${description}');

      elevate(role, 'admin');
      print('  ➜ ${role} elevated to ${elevated[role]}');
      print('  ➜ Anyone can ${description}');

      revokeAccess(elevated[role]!, resource, action);
      print('  ➜ ${elevated[role]} no longer has access');
    } else {
      print('  ✗ Unknown action: ${action}');
    }

    print('\n--- Permission Elevation Scenario ---');
    print('===================================');

    print('Elevating ${role} to admin role...');
    elevate(role, 'admin');

    print('Current role for ${role}: ${elevated[role]}');

    print('Attempting to access admin resource...');
    if (checkAccess(elevated[role]!, adminResource, 'read')) {
      print('  ✓ Access GRANTED (Role: ${elevated[role]})');
    } else {
      print('  ✗ Access DENIED (Insufficient permissions)');
    }

    print('Attempting to access admin resource again...');
    if (checkAccess(elevated[role]!, adminResource, 'write')) {
      print('  ✓ Access GRANTED (Role: ${elevated[role]})');
    } else {
      print('  ✗ Access DENIED (Insufficient permissions)');
    }

    print('===================================');
    print('\n--- Resource Access Matrix ---');
    print('------------------------------');
    for (final resource in resourceAccessMatrix.keys) {
      print('  $resource:');
      for (final role in roles) {
        print('    ${role}: ${resourceAccessMatrix[resource]!.contains(role) ? "✔" : "✗"}');
      }
      print('');
    }

    print('===================================');
  }

  String permissionsString(String role) {
    final Map<String, int> permissions = {};
    for (final resource in resourceAccessMatrix.keys) {
      if (resourceAccessMatrix[resource]!.contains(role)) {
        final String action = resourceAccessMatrix[resource]!.contains(role) ? '✔' : '✗';
        permissions['$resource-$action'] = (permissions['$resource-$action'] ?? 0) + 1;
      }
    }

    return permissions.entries.map((e) => '${e.key}: ${e.value}').toList().join(', ');
  }

  void listPermissions(String role) {
    print('Permissions: ${permissionsString(role)}');
