      var level = 1;
      for (final parent in roles) {
        if (parent == role) {
          break;
        }
        level++;
      }
      print('[$level] $padded → ${permissionsString(role)}');
    }
  }

  print('=== Role-Based Access Control System ===');
  print('=========================================');

  if (roles.isEmpty) {
