  );

  print('================================');
  print('Check access history:');
  checkAccessHistory('alice', adminResource, 'read');

  print('================================');
  print('Elevate bob to admin role...');
  elevate('bob', 'admin');

  testAccessControl(
    'admin',
    sensitiveResource,
    'write',
  );

  print('================================');
