        roleHierarchy[role] = 'admin';
      } else if (roles[role]!.contains('editor')) {
        roleHierarchy[role] = 'editor';
      } else if (roles[role]!.contains('moderator')) {
        roleHierarchy[role] = 'moderator';
      } else if (roles[role]!.contains('viewer')) {
        roleHierarchy[role] = 'viewer';
      }
    }

    for (var role in roles.keys) {
      if (roleHierarchy[role] == 'admin') {
        permissions['$resource/admin'] = true;
      }
