    }

    frequentItemsets.addAll(frequentCurrent);

    candidates.removeWhere((itemset) => frequentCurrent.contains(itemset));

    for (int i = 2; i <= k && frequentCurrent.isNotEmpty; i++) {
      Map<String, int> innerSupport = {};
      Set<String> innerCandidates = {};

      for (String itemset in frequentCurrent) {
