          continue;
        }
        List<String> itemsOfCurrent = itemset.toList();
        List<String> itemsetMinusOne = itemset.toList();
        itemsetMinusOne.removeLast();

        for (String item in itemsetMinusOne) {
          if (!innerSupport.containsKey(item)) {
            innerSupport[item] = 0;
          }
          innerSupport[item] = innerSupport[item]! + 1;
        }

        if (innerSupport.isNotEmpty) {
          innerCandidates.add(itemset);
        }
      }

      frequentCurrent.addAll(innerCandidates);

      if (innerCandidates.isNotEmpty) {
