  if (squares.isEmpty) {
    return result;
  }
  int n = squares.length;
  List<List<bool>> dp = List.generate(n, (_) => List.filled(n, false));
  List<List<int>> count = List.generate(n, (_) => List.filled(n, 0));
  for (int i = 0; i < n; i++) {
    dp[i][i] = true;
  }
  for (int len = 2; len <= n; len++) {
    for (int start = 0; start + len <= n; start++) {
      int end = start + len - 1;
      bool hasPair = false;
      for (int pivot = start + 1; pivot < end; pivot++) {
        if (dp[start][pivot] && dp[pivot][end]) {
          hasPair = true;
          break;
        }
      }
      if (hasPair) {
        dp[start][end] = true;
        count[start][end] = count[start][end] + 1;
      }
    }
  }
  for (int end = n - 1; end >= 0; end--) {
    for (int start = 0; start <= end; start++) {
      if (dp[start][end] && count[start][end] == k) {
        result.add(start);
      }
    }
  }
  return result;
}

