    List<int> curr = [
      ...rounds[i - 1],
      rounds[i][0] > rounds[i][1] ? rounds[i][0] : rounds[i][1]
    ];
    int score = curr[curr.length - 1];
    if (score > bestScore ||
        (score == bestScore && curr.length > best[0].length)) {
      update = true;
      best.add(List<int>.from(curr));
      if (score > bestScore) bestScore = score;
    } else if (score == bestScore && curr.length == best[0].length) {
      for (int j = 0; j < curr.length; j++) {
        if (curr[j] < best[0][j]) {
          update = true;
          break;
        }
      }
    }
    if (!update) {
      best[0] = curr;
      bestScore = curr[curr.length - 1];
    }
  }
  return best;
}

