  ends.add(runs.length);
  List<int> blockSums = [];
  for (int i = 0; i < ends.length - 1; i++) {
    blockSums.add(samples.sublist(ends[i], ends[i + 1]).fold(0, (a, b) => a + b));
  }
  return blockSums;
}

