Map<String, int> fn0(List<int> logs) {
  int n = logs.length;
  if (n == 0) return {"index": -1, "size": 0};
  int left = 0, right = n;
  while (left < right) {
    int mid = left + (right - left) ~/ 2;
    if (logs[mid] <= 0) left = mid + 1;
    else right = mid;
  }
  int idx = left;
  int sum = 0, maxLen = 0;
  for (int i = 0; i < n; i++) {
    sum += logs[i];
    if (i >= idx && logs[i] <= 0) {
      int deleted = logs[i];
      sum -= deleted;
      if (deleted > maxLen) maxLen = deleted;
    }
  }
