class Point {
  final double x;
  final double y;

  Point(this.x, this.y);

  @override
  String toString() => 'Point($x, $y)';

  static const double EPSILON = 1.0E-6;

  static bool pointInCircle(Point p, Point center, double radius) {
    double dx = p.x - center.x;
    double dy = p.y - center.y;
    return dx * dx + dy * dy <= radius * radius;
  }

  static bool pointInRectangle(Point p, Point point1, Point point2) {
    return point1.x <= p.x && p.x < point2.x &&
        point1.y <= p.y && p.y < point2.y;
  }
}

class Rectangle {
  final double x1;
  final double y1;
  final double x2;
  final double y2;

  Rectangle(this.x1, this.y1, this.x2, this.y2);

  Rectangle.square(double size)
      : this(size, size, size, size);

  Rectangle.unit()
      : this(0.0, 0.0, 1.0, 1.0);

  Rectangle.random(Random rand)
      : this(rand.nextDouble() * 200 - 100,
             rand.nextDouble() * 200 - 100,
             rand.nextDouble() * 200 + 100,
             rand.nextDouble() * 200 + 100);

  Rectangle.centered(double centerX, double centerY)
      : this(centerX - 50, centerY - 50, centerX + 50, centerY + 50);

  Rectangle.unitIn(Rectangle enclosing)
      : this(enclosing.x1, enclosing.y1, enclosing.x2, enclosing.y2);

  Rectangle.halfWidth(Rectangle enclosing)
      : this(enclosing.x1 + enclosing.halfWidth,
             enclosing.y1,
             enclosing.x1 + enclosing.halfWidth * 2,
             enclosing.y2);

  Rectangle.halfHeight(Rectangle enclosing)
      : this(enclosing.x1, enclosing.y1 + enclosing.halfHeight,
             enclosing.x2,
             enclosing.y1 + enclosing.halfHeight * 2);

  bool pointIn(Point p) {
    return p.x >= x1 && p.x < x2 && p.y >= y1 && p.y < y2;
  }

  bool contains(Rectangle other) {
    return pointIn(other.p1) && pointIn(other.p2);
  }

  Point get center =>
      Point((x1 + x2) / 2, (y1 + y2) / 2);

  double get halfWidth => (x2 - x1) / 2;

  double get halfHeight => (y2 - y1) / 2;

  @override
  String toString() => 'Rectangle(center: (${center.x}, ${center.y}), halfWidth: $halfWidth, halfHeight: $halfHeight)';
}

