class Rectangle {
  final double x1, y1, x2, y2;
  final double width, height;

  const Rectangle(this.x1, this.y1, this.x2, this.y2);

  const Rectangle.originToUnit()
      : this(0, 0, 1, 1);

  const Rectangle.unitToUnit()
      : this(0, 0, 1, 2)
          ..width = 1
          ..height = 2;

  Rectangle.square(this.x1, this.y1, this.width):
      this(x1, y1, x1 + 2 * width, y1 + 2 * height);

  Rectangle.circular(this.x1, this.y1, this.radius)
      : this(x1 - radius, y1 - radius, x1 + radius, y1 + radius);

  Rectangle.fromPoints(Point p1, Point p2)
      : this(p1.x, p1.y, p2.x, p2.y);

  Rectangle.expand(this.x1, this.y1, double amount)
      : this(x1 - amount, y1 - amount, x1 + amount, y1 + amount);

  Rectangle.contract(this.x1, this.y1, double amount)
      : this(x1 + amount, y1 + amount, x1 - amount, y1 - amount);

  Rectangle.mirrorAbout(this.x1, this.y1, this.x2, this.y2)
      : this(x1, y1, x2, y2);

  Rectangle.translate(this.x1, this@:y1, this.x2, this.y2)
      : this(x1 + dx, y1 + dy, x2 + dx, y2 + dy);

  Rectangle.rotate(this.x1, this.y1, this.x2, this.y2, double angle)
      : this(x1 + (x2 - x1) * cos(angle) - (y2 - y1) * sin(angle),
          y1 + (x2 - x1) * sin(angle) + (y2 - y1) * cos(angle),
          x2 + (x2 - x1) * cos(angle) + (y2 - y1) * sin(angle),
          y2 + (x2 - x1) * sin(angle) - (y2 - y1) * cos(angle));

  Rectangle.clip(this.x1, this.y1, this.x2, this.y2, this.dx, this.dy)
      : this(dx > 0 ? x1 + dx : x1,
          dy > 0 ? y1 + dy : y1,
          dx < 0 ? x2 + dx : x2,
          dy < 0 ? y2 + dy : y2);

  Rectangle.union(this.x1, this.y1, this.x2, this.y2, this.dx, this.dy)
      : this(dx > 0 ? x1 : x2 + dx,
          dy > 0 ? y1 : y2 + dy,
          dx < 0 ? x2 : x1 + dx,
          dy < 0 ? y2 : y1 + dy);

  Rectangle.intersect(this.x1, this.y1, this.x2, this.y2, this.dx, this.dy)
      : this(dx > 0 && dy > 0 ? x1 : null,
          dy > 0 && dx < 0 ? y1 : null,
          dx < 0 && dy > 0 ? x2 : null,
          dx < 0 && dy < 0 ? y2 : null);

  Rectangle.wrap(this.x1, this.y1, this.x2, this.y2, this.minX, this.minY,
      this.maxX, this.maxY)
      : this(minX < x1 ? minX : x1, minY < y1 ? minY : y1,
          maxX > x2 ? maxX : x2, maxY > y2 ? maxY : y2);

  final double dx, dy;
  final double x1, y1, x2, y2;
  final double width, height;
  final double minX, maxX, minY, maxY;

  double get centerX => (x1 + x2) / 2;
  double get centerY => (y1 + y2) / 2;

  double get halfWidth => width / 2;
  double get halfHeight => height / 2;

  bool get isZero => width <= 0 || height <= 0;

  bool contains(Point p) =>
      dx < 0 ? (x1 <= p.x && p.x < x1 + 2 * dx) : (x1 < p.x && p.x <= x1 + 2 * dx);

  bool intersects(Rectangle r) =>
      dx < 0 && dy < 0 ? r.x1 < x1 && x2 < r.x2 && r.y1 < y1 && y2 < r.y2 :
      dx > 0 && dy > 0 ? r.x1 < x1 && x2 < r.x2 && r.y1 < y1 && r.y2 < y2 :
      dx > 0 || dy > 0 ? r.contains(Point(x1, y1)) || r.contains(Point(x1 + 2 * dx, y1)) ||
          r.contains(Point(x1, y1 + 2 * dy)) || r.contains(Point(x1 + 2 * dx, y1 + 2 * dy)) :
      true;

  Rectangle get mirrorAbout(double axis) =>
      this(y1, x1 + 2 * dx, y2, x2 - 2 * dx)
        ..mirrorAbout(axis);

  Rectangle get translate(double dx, double dy) =>
      this(x1 + dx, y1 + dy, x2 + dx, y2 + dy);

  Rectangle get rotate(double angle) =>
      this(x1 + (x2 - x1) * cos(angle) - (y2 - y1) * sin(angle),
          y1 + (x2 - x1) * sin(angle) + (y2 - y1) * cos(angle),
          x2 + (x2 - x1) * cos(angle) + (y2 - y1) * sin(angle),
          y2 + (x2 - x1) * sin(angle) - (y2 - y1) * cos(angle));

  Rectangle get clipped(Rectangle clipping) =>
      this.clip(clipping.x1, clipping.y1, clipping.x2, clipping.y2, dx, dy);

  Rectangle get union(Rectangle r) =>
      this.union(r.x1, r.y1, r.x2, r.y2, 0, 0);

  Rectangle get intersect(Rectangle r) =>
      this.intersect(r.x1, r.y1, r.x2, r.y2, 0, 0);

  Rectangle get wrapped(Rectangle bounds) =>
      this.wrap(bounds.x1, bounds.y1, bounds.x2, bounds.y2, bounds.minX, bounds.minY,
          bounds.maxX, bounds.maxY);

  @override
  String toString() => 'Rectangle(center: (${centerX}, ${centerY}), '
      'halfWidth: $halfWidth, halfHeight: $halfHeight)';
}

