import 'dart:math';

class Point {
  final double x, y;

  Point(this.x, this.y);

  @override
  String toString() => 'Point($x, $y)';
}

class Rectangle {
  final double x1, y1, x2, y2;

  Rectangle(this.x1, this.y1, this.x2, this.y2);

  Rectangle.origin()
      : this(0, 0, 100, 100);

  Rectangle.unit()
      : this(0, 0, 100, 100);

  Rectangle.square(double side)
      : this(0, 0, side, side);

  Rectangle.centered(double centerX, double centerY, double halfWidth, double halfHeight) {
    final double x1 = centerX - halfWidth;
    final double y1 = centerY - halfHeight;
    final double x2 = centerX + halfWidth;
    final double y2 = centerY + halfHeight;
    return Rectangle(x1, y1, x2, y2);
  }

  double area() => (x2 - x1) * (y2 - y1);

  bool contains(Point p) =>
      x1 < p.x && p.x < x2 && y1 < p.y && p.y < y2;

  bool contains(Rectangle r) =>
      contains(r.x1, r.y1) && contains(r.x2, r.y2);

  bool overlaps(Rectangle r) =>
      !(contains(r.x1, r.y1) == contains(r.x2, r.y2));

  Rectangle union(Rectangle r) {
    final double x1 = min(x1, r.x1);
    final double y1 = min(y1, r.y1);
    final double x2 = max(x2, r.x2);
    final double y2 = max(y2, r.y2);
    return Rectangle(x1, y1, x2, y2);
  }

  bool isOrigin() => x1 == 0 && y1 == 0 && x2 == 100 && y2 == 100;

  bool isUnit() => x1 == 0 && y1 == 0 && x2 == 100 && y2 == 100;

  bool isSquare() => x1 == 0 && y1 == 0 && x2 == 100 && y2 == 100;

  @override
  String toString() => 'Rectangle(center: ($centerX, $centerY), halfWidth: $halfWidth, halfHeight: $halfHeight)';

  final double centerX = (x1 + x2) / 2;
  final double centerY = (y1 + y2) / 2;
  final double halfWidth = (x2 - x1) / 2;
  final double halfHeight = (y2 - y1) / 2;
}

