  Set<int> pointSet = {};

  for (int i = 0; i < n; i++) {
    pointSet.add(i);
  }

  List<List<double>> centroids = List.generate(k, (_) => [0.0, 0.0]);

  int iteration = 0;

  while (pointSet.length > k) {

    for (int i = 0; i < k; i++) {
      centroids[i] = [0.0, 0.0];
    }

    List<int> indices = List.generate(n, (_) => rand.nextInt(n));

    for (int i = 0; i < k; i++) {
      centroids[i] = [0.0, 0.0];
    }

    for (int j = 0; j < n; j++) {

      int idx = indices[j];
      int bestCluster = 0;
      double minDist = double.infinity;

      for (int c = 0; c < k; c++) {
        double dist =
            sqrt(pow(points[idx][0] - centroids[c][0], 2) +
                pow(points[idx][1] - centroids[c][1], 2));
        if (dist < minDist) {
          minDist = dist;
          bestCluster = c;
        }
      }

      if (bestCluster != labels[idx]) {
        labels[idx] = bestCluster;
        clusters[bestCluster].add(idx);
      }

      pointSet.remove(idx);

      for (int c = 0; c < k; c++) {
        if (c != bestCluster) {
          centroids[c] = [centroids[c][0] - points[idx][0],
              centroids[c][1] - points[idx][1]];
        } else {
          centroids[c] = [points[idx][0], points[idx][1]];
        }
      }

      if (labels[idx] == 0) {
        centroids[0][0] += points[idx][0];
        centroids[0][1] += points[idx][1];
      } else if (labels[idx] == 1) {
        centroids[1][0] += points[idx][0];
