  for (int i = 0; i < k; i++) {
    centroids[i] = points[i];
  }

  List<int> pointsInCluster(int c) {
    List<int> indices = [];
    for (int i = 0; i < n; i++) {
      if (clusterLabels[i][c] == c) {
        indices.add(i);
      }
    }
    return indices;
  }

  bool isConverged() {
    for (int i = 0; i < n; i++) {
      if (find(i) != i) return false;
    }
    return true;
  }

  bool needsReassignment() {
    for (int c = 0; c < k; c++) {
      final List<int> cluster = pointsInCluster(c);
      if (cluster.length < 2) continue;
      double mean = 0.0;
      for (final int idx in cluster) {
        mean += points[idx][0];
      }
      mean = mean / cluster.length;
      double minDist = double.infinity;
      for (int j = 0; j < k; j++) {
