          double dist = 0.0;
          for (final int idx in pointsInCluster(j)) {
            final List<double> p = points[idx];
            final List<double> m = centroids[j];
            dist += pow(p[0] - m[0], 2) + pow(p[1] - m[1], 2);
          }
          if (dist < minDist) minDist = dist;
        }
      }
      if (minDist <= eps) {
        return false;
      }
    }
    return true;
  }

  bool allDistinct() {
    for (int c = 0; c < k; c++) {
      if (pointsInCluster(c).length > 1) return false;
    }
    return true;
  }

  bool improvedCentroids() {
    for (int c = 0; c < k; c++) {
      final List<int> cluster = pointsInCluster(c);
      if (cluster.length < 2) continue;
      double mean = 0.0;
      for (final int idx in cluster) {
        final List<double> p = points[idx];
