        for (final int idx in cluster) {
          final List<double> p = points[idx];
          sum += pow(p[0] - m[0], 2) + pow(p[1] - m[1], 2);
        }
        if (sum < minDist) {
          minDist = sum;
        }
      }
      if (minDist <= eps) {
        clusterLabels[c][c] = rand.nextInt(k) + 1;
        changed = true;
      }
    }

    if (changed) {
      converged = false;
    } else if (allDistinct()) {
      converged = true;
    } else if (needsReassignment()) {
      if (improvedCentroids()) {
        changed = true;
      } else {
        break;
      }
    } else {
      break;
    }

    if (changed) {
      currentIter++;
    }
  }

  bool convergedOk = converged && improvedCentroids() && allDistinct();
  print('Converged in $currentIter iteration(s).');
  if (convergedOk) {
