    [1, 2, 3],
    [4, 5, 6],
    [7, 8, 9],
  ];

  int rows = grid.length;
  int cols = grid[0].length;

  List<List<int>> tree = [];
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      if (i == 0 || i == rows - 1 || j == 0 || j == cols - 1) {
        tree.add([i, j, grid[i][j]]);
      }
    }
  }

  List<int> queue = [];
  for (var node in tree) {
    queue.add(node[0]);
    queue.add(node[1]);
  }

