  while (queue.isNotEmpty) {
    int current = queue.removeAt(0);
    int row = current ~/ cols;
    int col = current % cols;
    bfsResult.add(grid[row][col]);
    for (int nextRow = row - 1; nextRow <= row + 1; nextRow++) {
      for (int nextCol = col - 1; nextCol <= col + 1; nextCol++) {
        if (nextRow >= 0 && nextRow < rows && nextCol >= 0 && nextCol < cols) {
          queue.add(nextRow * cols + nextCol);
        }
      }
    }
  }

  print('Breadth-first traversal: $bfsResult');
}

