String fn0(String encoded, int minBrightness) {
  if (encoded.isEmpty) return "";
  var parts = encoded.split(',');
  int? target;
  for (var i = 0; i < parts.length; i++) {
    var p = parts[i];
    if (p.isEmpty) continue;
    var colon = p.indexOf(':');
    if (colon <= 0 || colon == p.length - 1) continue;
    var count = int.parse(p.substring(0, colon));
    var brightness = int.parse(p.substring(colon + 1));
    if (count > 0 && brightness >= minBrightness) {
      target = i;
      break;
    }
  }
  if (target == null) return "";
  var result = '';
  for (var i = 0; i < parts.length; i++) {
    if (i == target) result += '*';
    else result += parts[i];
  }
  var count = int.parse(result.substring(0, result.indexOf(':')));
  return count > 0 ? result : '';
}

